"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47262"],{55027(e){e.exports=JSON.parse('{"id":"FIN-246","slug":"corporate-bond","term":"Corporate Bond","also_known_as":[],"difficulty":"Beginner","definition":"A corporate bond is a bond issued by a company to borrow money from investors, paying regular interest and repaying the face value at maturity.","explanation":["Companies issue bonds to raise money for expansion, acquisitions, refinancing existing debt or general operations. Bonds allow them to borrow large amounts, often for many years, from a wide range of investors.","Corporate bonds usually pay higher interest than government bonds, because companies are more likely to default. The extra yield over a comparable government bond is called the credit spread.","Credit rating agencies assess how likely a company is to repay and assign ratings. Bonds with high ratings are called investment grade. Bonds with lower ratings, from companies with weaker finances, are called high-yield or, less formally, junk bonds. They pay higher interest to compensate for greater risk.","For example, a financially strong company might issue a ten-year bond paying 5% when government bonds pay 4%, while a weaker company might need to offer 8% or more.","Corporate bondholders are paid before shareholders if the company runs into difficulty, but they do not share in the company\'s growth. Their return is limited to the interest and repayment of principal."],"note":"","total":1500,"prev":{"slug":"core-inflation","term":"Core Inflation"},"next":{"slug":"corporate-finance","term":"Corporate Finance"}}')}}]);